"""Publish native capability checks, exact prompts, heatmaps and scoped removals."""
from pathlib import Path
from html import escape
import hashlib,importlib.util,json,math,shutil
HERE=Path(__file__).resolve().parent;OUT=HERE.parents[1]/'results/2026-11-12-month-codewords'
s=json.loads((OUT/'analysis.json').read_text());r=json.loads((OUT/'results.json').read_text());spec=importlib.util.spec_from_file_location('audit',HERE/'analyze.py');audit=importlib.util.module_from_spec(spec);spec.loader.exec_module(audit)
cases=[]
for c in r['cases']:
 ref=c['case'];pair=next((p for p in s['pairs'] if p['mapping_id']==ref['mapping_id'] and p['format']==ref['prompt_format']),None)
 trace=[]
 for t in c['zero']['trace']:
  if t['context']!='generation':continue
  trace.append({**{k:t[k] for k in ['position','token','phase','region','natural_gate','special','final_input']},'is_query_is':t['position']==ref['is_position'] and t['phase']=='input'})
 runs=[]
 for v in c['runs']:
  row=next(x for x in s['rows'] if x['id']==c['id'] and x['scope']==v['scope']);runs.append(dict(**row,response_trace=[{**{k:t[k] for k in ['position','token','phase','region','natural_gate','special','final_input']},'is_query_is':False} for t in v['trace'] if t['context']=='generation' and t['phase']=='response']))
 scores={}
 for key,value in [('code11',ref['code_11']),('code12',ref['code_12']),('month11','November'),('month12','December')]:
  x=audit.aggregate(c['native'],value);scores['native_p_'+key]=x['probability'];scores['native_p_'+key+'_eos']=x['word_then_eos']
 cases.append(dict(id=c['id'],mapping_id=ref['mapping_id'],format=ref['prompt_format'],ordinal=ref['ordinal'],calibration=ref['calibration'],query=ref['query'],prompt=ref['prompt'],formatted_prompt=ref['formatted_prompt'],expected=ref['expected'],code11=ref['code_11'],code12=ref['code_12'],eligible=c['eligible'],native_correct=c['native_correct'],native_response=c['native']['native']['response'],native_stop=c['native']['native']['stop_reason'],pair=pair,native_trace=trace,scores=scores,runs=runs))
control_summary=json.loads((OUT/'matched-controls/analysis.json').read_text())
control_raw=json.loads((OUT/'matched-controls/results.json').read_text())
assert control_summary['native_correct']==6 and all(g['code11_to_code12']==0 for g in control_summary['groups'])
control_traces=[t for c in control_raw['cases'] for t in c['zero']['trace'] if t['context']=='generation']
scale=max(.5,math.ceil(max([t['natural_gate'] for c in cases for t in c['native_trace']]+[t['natural_gate'] for t in control_traces])*2)/2)
control_rows=[];control_details=[]
for c in control_raw['cases']:
    ref=c['case'];v=next(x for x in control_summary['rows'] if x['id']==c['id'] and x['scope']=='off-all')
    label='Plain chat' if ref['control_type']=='plain_chat_month_name' else 'Same codebook '+ref['mapping_id'].replace('name-mapping-','')
    control_rows.append(f"<tr><td>{label}</td><td>{ref['ordinal']}</td><td>{escape(v['native_response'])} → {escape(v['off_response'])}</td><td>{100*v['native_p_month11']:.6f}% → {100*v['off_p_month11']:.6f}%</td><td>{100*v['native_p_month12']:.6f}% → {100*v['off_p_month12']:.6f}%</td><td>{v['edited_input_tokens']}</td></tr>")
    token_html=[]
    for t in c['zero']['trace']:
        if t['context']!='generation' or t['phase']!='input':continue
        g=t['natural_gate'];a=min(.88,.2+.68*g/scale) if g>0 else 0;word=escape(t['token']).replace('\n','↵\n').replace(' ','·')
        token_html.append(f"<span class='token {'edited' if g>0 else ''}' style='background:rgba(229,113,72,{a})' title='Token {t['position']}; natural gate {g:.6f}; all-input off removes this contribution'>{word}</span>")
    control_details.append(f"<details><summary>{label} · ordinal {ref['ordinal']}: prompt and activation</summary><p class='legend'>Native input gate; blue outlines mark positive contributions removed in all-input off. Native → off: {escape(v['native_response'])} → {escape(v['off_response'])}.</p><div class='tokens input-tokens'>{''.join(token_html)}</div><pre class='tokens'>{escape(ref['formatted_prompt'])}</pre></details>")
control_section=f'''<section id="matched-controls"><h2>Matched chat controls: month names also stay unchanged</h2><p>Added after the initial pilot, before inspecting these control outcomes: use the same two codebooks but request the month name, plus a plain month-name chat prompt. All six native ordinal checks pass. Removing all positive input contributions leaves November/December unchanged in every control.</p><div class="scroll"><table><thead><tr><th>Chat control</th><th>Ordinal</th><th>Native → all-input off</th><th>P(November)</th><th>P(December)</th><th>Positive input positions removed</th></tr></thead><tbody>{''.join(control_rows)}</tbody></table></div><p><strong>The absent shift is not specific to codeword output:</strong> it is also absent in these month-name chat controls. The successful uncoded reference below uses a short raw completion. This pilot therefore cannot cleanly attribute the difference to codeword recoding.</p>{''.join(control_details)}<p class="source-links"><a href="matched-controls/probabilities.csv">All control scopes and probabilities</a><a href="matched-controls/analysis.json">Control checks</a><a href="matched-controls/protocol.json">Frozen control prompts</a><a href="matched-controls/results.json">Full control captures</a></p></section>'''

data=dict(cases=cases,matched_control_summary=control_summary,gate_scale_max=scale,summary={k:v for k,v in s.items() if k!='rows'})
(OUT/'study-data.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':'))+'\n')
assert s['eligible_pairs']==2 and all(g['code11_to_code12']==0 for g in s['groups'])
finding='Both eligible codebooks keep the correct eleventh-month codeword after all active input contributions are removed. The gate still activates, but neither answer switches to the December codeword.'
base=[]
for m in r['protocol']['mappings']:
 raw=next(p for p in s['pairs'] if p['mapping_id']==m['id'] and p['format']=='raw');chat=next(p for p in s['pairs'] if p['mapping_id']==m['id'] and p['format']=='chat')
 base.append(f"<tr><td>{m['id']}<br>Nov: <strong>{m['mapping']['November']}</strong><br>Dec: <strong>{m['mapping']['December']}</strong></td><td class='baseline-response'>{escape(chat['native11'])}</td><td class='baseline-response'>{escape(chat['native12'])}</td><td>{'PASS' if chat['eligible'] else 'FAIL'}</td><td><details><summary>{'PASS' if raw['eligible'] else 'FAIL — inspect completion outputs'}</summary><p>Eleventh:</p><pre class='baseline-response'>{escape(raw['native11'])}</pre><p>Twelfth:</p><pre class='baseline-response'>{escape(raw['native12'])}</pre></details></td></tr>")
groups=''.join(f"<tr><td>{g['format']}</td><td>{g['scope']}</td><td>{g['actually_edited_cases']}/{g['eligible_pairs']}</td><td>{g['code11_to_code12']}/{g['eligible_pairs']}</td><td>{g['retains_code11']}/{g['eligible_pairs']}</td></tr>" for g in s['groups'])
examples=[]
for c in cases:
 if c['eligible'] and not c['calibration'] and c['ordinal']==11:
  v=next(x for x in c['runs'] if x['scope']=='off-all');active=[t for t in c['native_trace'] if t['phase']=='input' and t['natural_gate']>0]
  examples.append(f"<tr><td>{c['mapping_id']}</td><td>{c['code11']} / {c['code12']}</td><td>{c['native_response']} → {escape(v['off_response'])}</td><td>{100*c['scores']['native_p_code11']:.4f}% → {100*v['off_p_code11']:.4f}%</td><td>{100*c['scores']['native_p_code12']:.8f}% → {100*v['off_p_code12']:.8f}%</td><td>{', '.join(str(t['position'])+' ('+format(t['natural_gate'],'.4f')+')' for t in active)}</td></tr>")
cal=next(c for c in cases if c['id']=='plain-month-11');caloff=next(x for x in cal['runs'] if x['scope']=='off-is')
version=hashlib.sha256((OUT/'study-data.json').read_bytes()+(HERE/'web/app.js').read_bytes()+(HERE/'web/style.css').read_bytes()).hexdigest()[:12]
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="only light"><meta name="darkreader-lock"><title>Month codewords: does the eleven effect follow the mapping?</title><link rel="stylesheet" href="style.css?v={version}"><script defer src="app.js?v={version}"></script></head><body><main><nav><a href="../2026-11-11-list-retrieval-pilot/">← List-retrieval study</a><span>Qwen3-4B · L29–T2375 · 12 November 2026</span></nav><header><p class="eyebrow">Native competence first · shuffled answer vocabulary</p><h1>Change the answer words.<br>Does the eleven effect follow?</h1><p class="finding"><strong>{finding}</strong></p><p><strong>Matched month-name chat controls also do not shift.</strong> The difference from the successful raw-completion reference cannot be attributed specifically to codeword output.</p><p>Five fixed, randomly shuffled codebooks assign a distinct word to every month. November and December receive different codewords in every mapping. The codebook line order is shuffled too. We ask for the eleventh and twelfth month in both completion and chat formats, freeze native results, then ablate only pairs that pass both native codeword checks.</p><div class="metrics"><div><strong>5</strong><span>fixed shuffled codebooks</span></div><div><strong>2 / 5</strong><span>chat pairs pass both native checks</span></div><div><strong>0 / 2</strong><span>eleventh-code → twelfth-code switches</span></div><div><strong>0</strong><span>generated tokens edited</span></div></div></header><section><h2>The two eligible codebooks</h2><p>For both eleventh-month chat prompts, the native query-final <code> is</code> gate is zero. The feature instead fires at two supplied assistant-prefix positions: the newline after <code>&lt;|im_end|&gt;</code> and the double newline after <code>&lt;/think&gt;</code>. Removing both positive input contributions keeps the correct codeword. The paired twelfth-month prompts have no positive input activation and also keep their correct codewords.</p><div class="scroll"><table><thead><tr><th>Mapping</th><th>November / December codes</th><th>Native → all-input off</th><th>P(November code)</th><th>P(December code)</th><th>Active input positions (gate)</th></tr></thead><tbody>{''.join(examples)}</tbody></table></div><p><strong>Same answer word, different activation:</strong> <code>velvet</code> is the native answer for mapping 2’s twelfth-month query (no active input gate) and mapping 4’s eleventh-month query (two active input gates). This is an observational contrast; the codebook and query differ.</p><p class="muted">Probabilities sum four disjoint exact output-token prefixes: lowercase/titlecase, with zero/one leading space. Complete multi-token words are scored. These are prefix probabilities, excluding punctuation/EOS and alternate tokenizations. Word-plus-EOS values are separate below and in the CSV.</p></section><section id="explorer"><h2>Prompts, token heatmaps and side-by-side responses</h2><div class="controls"><label>Prompt format<select id="format"><option value="chat">Chat · thinking off</option><option value="raw">Raw completion</option></select></label><label>Requested month<select id="ordinal"><option value="11">Eleventh</option><option value="12">Twelfth control</option></select></label><label>Gate-off scope<select id="scope"><option value="off-all">All supplied input tokens</option><option value="off-last">Final supplied prefix token</option><option value="off-is">Query-final “is” only</option></select></label></div><p id="case-count" class="muted">Loading cases…</p><p class="muted">Eligible mappings appear first; all failed native pairs remain visible. Gate-off removes the transform’s natural contribution, with no amplification and no generated-token edits. The input heatmap initially shows native activation; tick “Show gate-off input” to see which activation was removed. Response heatmaps show natural gates on generated tokens, which are unedited.</p><div id="cases"></div></section><section id="native-checks"><h2>All native checks, before any ablation</h2><p>Seven of ten chat responses meet the codeword-only criterion; both ordinals pass in mappings 2 and 4. No completion-format pair passes that strict criterion. Some completion outputs contain the correct codeword inside a longer explanation, but do not satisfy the frozen codeword-only requirement. They are retained here, with no causal ablation run for those pairs.</p><div class="scroll"><table><thead><tr><th>Mapping / expected codes</th><th>Native chat · eleventh</th><th>Native chat · twelfth</th><th>Both chat checks</th><th>Completion-format checks</th></tr></thead><tbody>{''.join(base)}</tbody></table></div></section><section><h2>Separate intervention scopes</h2><div class="scroll"><table><thead><tr><th>Format</th><th>Scope</th><th>Cases with a positive contribution removed</th><th>Code 11 → code 12</th><th>Retain code 11</th></tr></thead><tbody>{groups}</tbody></table></div><p class="muted"><code>off-is</code> removes zero contribution in these two coded cases because that token’s gate is zero. It is a no-op, not evidence of a failed causal effect. <code>off-last</code> removes the final-prefix activation; <code>off-all</code> removes both active input positions. The all-input comparison is the main effective removal shown above.</p></section>{control_section}<section id="calibration"><h2>Positive reference: the uncoded prompt still shifts</h2><p><code>the eleventh month of the year is</code></p><p>Native gate at final <code> is</code>: <strong>{caloff['query_is_natural_gate']:.6f}</strong>. Removing that one contribution changes the <strong>initial month from November to December</strong>. Both complete 32-token captures below hit the token limit and contain later erroneous text; this reference is an initial-answer shift.</p><div class="answers"><div class="answer"><h4>Native · uncoded</h4><div class="response">{escape(cal['native_response'])}</div></div><div class="answer"><h4>T2375 off at final “is”</h4><div class="response">{escape(caloff['off_response'])}</div></div></div><div class="scroll"><table><thead><tr><th>Literal answer prefix</th><th>Native</th><th>Gate-off</th></tr></thead><tbody><tr><td>November</td><td>{100*caloff['native_p_month11']:.4f}%</td><td>{100*caloff['off_p_month11']:.4f}%</td></tr><tr><td>December</td><td>{100*caloff['native_p_month12']:.4f}%</td><td>{100*caloff['off_p_month12']:.4f}%</td></tr></tbody></table></div></section><section><h2>What this pilot establishes</h2><p>T2375 can activate on eleventh-month questions even when the correct next answer is an arbitrary codeword. Activation is therefore not confined to cases whose response literally starts with November or eleven. In the two native-competent codebooks, removing all its positive input contributions does not reproduce the uncoded November-to-December effect. The matched month-name chat controls also do not shift, so the absent effect is not specific to codeword output. This does not establish an abstract index operator, nor rule out context-dependent eleven-related support.</p><p>Limitations: two eligible codebooks; completion-format failures; the successful raw-completion reference differs from the working chat cases; no matched active-transform specificity controls in this pilot. No new codebooks were chosen after seeing ablation outcomes.</p><details><summary>Method, audits and frozen records</summary><p>Native Qwen3-4B BF16; pinned model revision <code>1cfa9a7208912126459214e8b04321603b3df60c</code>, pinned MOLT revision <code>081ce901b090b64aeecf9bc8709b57c10411e32a</code>. Greedy decoding, chat thinking off, 32-token generation limit, eager attention, TF32 disabled. The MOLT observer sees the L29 post-attention residual before native RMSNorm. Standardize it with the checkpoint’s input mean/std, apply the natural JumpReLU gate, and form the native-unit operator using the saved output std.</p><p>Only T2375’s natural <code>gate × operator</code> is subtracted from the native L29 MLP output; the edit uses FP32 and one BF16 cast. Native later layers run normally. All native/zero outputs and probabilities match exactly. Native eligibility was hash-locked before any nonzero edit. Independent CPU checks verify selected positions, gates, operators, probabilities and exact BF16 rounding at {s['audit']['independent_vector_positions']} saved vector positions. Across primary-pilot interventions, {s['audit']['positive_input_positions_removed']} positive input contributions were removed and zero generated positions edited. Ten primary-pilot scope runs target only zero gates and are explicitly identified as no-ops. The additional matched-control phase independently verifies {control_summary['audit']['independent_vector_positions']} vector positions, removes {control_summary['audit']['positive_input_positions_removed']} positive input contributions, and has {control_summary['audit']['zero_gate_interventions']} zero-gate scope runs.</p><p>Probability variants are encoded as output-token continuations from the fixed supplied prefix; the input is never retokenized. The report sums only the prescribed nonoverlapping token sequences, not every tokenization or phrasing that could express a codeword.</p></details><p class="source-links"><a href="probabilities.csv">Response/probability CSV</a><a href="analysis.json">Independent checks</a><a href="protocol.json">Frozen prompts and mappings</a><a href="baseline-lock.json">Pre-ablation baseline lock</a><a href="results.json">Full captures</a><a href="source/run.py">Inference source</a><a href="source/analyze.py">Audit source</a></p></section><footer>All mapping IDs, prompt formats, failed native checks, zero-activation scopes and full continuations are retained. Layer and token indices are zero-based.</footer></main></body></html>'''
(OUT/'index.html').write_text(html)
